  ['homebrewForge', '🛠️', 'Homebrew Forge'], ['hybridAncestry', '🧬', 'Hybrid Ancestry'], ['rules', '⚙️', 'Rules & Mechanics'], ['downtime', '⏳', 'Downtime & Bases'],
  ['sessions', '📅', 'Sessions & Timeline'], ['secrets', '🔒', 'Secrets & Reveals'], ['library', '📚', 'Library & Compendium']
